import com.surprising.aeron.client.SurprisingAeronClient;
import com.surprising.aeron.protocol.*;
import com.surprising.product.api.ProductLine;
import java.time.Duration;
import java.util.*;
import java.nio.file.*;
import java.security.MessageDigest;
import tools.jackson.databind.ObjectMapper;
public class MatchAuditMain {
 public static void main(String[] args) throws Exception {
  ProductLine product=ProductLine.requireExternalCode(System.getProperty("surprising.aeron.product-line"));
  String asset=product==ProductLine.INVERSE_PERPETUAL?"BTC":"USDT";
  long funds=0,locked=0,positive=0,negative=0; int positionCount=0;
  var netByInstrument=new TreeMap<String,Long>();var accounts=new ArrayList<Map<String,Object>>();
  try(var client=SurprisingAeronClient.connect(product,List.of("127.0.0.1"),"127.0.0.1",Duration.ofSeconds(30))) {
   for(int index=0;index<1000;index++) {
    long user=50_000_000_000L+25601L*1000+index,seq=System.nanoTime();
    var header=CoreMessageHeader.query(CoreMessageType.USER_STATE_QUERY,UUID.randomUUID(),product,CommandSource.OPERATIONS,0x4D41544348415544L,seq,user,seq,seq);
    var response=client.submit(new CoreMessage(header,new byte[0]));
    if(response.status()!=ResponseStatus.OK)throw new IllegalStateException("query failed");
    var state=CoreStateQueryCodec.decodeUserState(response.data());
    if(state.productLine()!=product||state.userId()!=user||!state.reservations().isEmpty())throw new IllegalStateException("identity/reservation mismatch user="+user);
    var account=new LinkedHashMap<String,Object>();account.put("userId",user);account.put("balances",state.balances());account.put("positions",state.positions());accounts.add(account);
    for(var b:state.balances()) {
     if(!b.asset().equals(asset)||b.availableUnits()<0||b.lockedUnits()<0)throw new IllegalStateException("balance mismatch");
     funds=Math.addExact(funds,Math.addExact(b.availableUnits(),b.lockedUnits()));locked=Math.addExact(locked,b.lockedUnits());
    }
    for(var p:state.positions()) {
     if(!p.marginAsset().equals(asset)||p.positionMarginUnits()<0||p.entryPriceTicks()!=100||p.realizedPnlUnits()!=0)throw new IllegalStateException("position mismatch");
     long qty=p.signedQuantitySteps();if((index%2==0&&qty>0)||(index%2!=0&&qty<0))throw new IllegalStateException("position side mismatch");
     positionCount++;if(qty>0)positive=Math.addExact(positive,qty);else negative=Math.addExact(negative,Math.negateExact(qty));
     netByInstrument.merge(p.instrumentId(),qty,Math::addExact);
    }
   }
  }
  if(funds!=1_000_000_000_000_000L||locked!=0||positive!=negative||netByInstrument.values().stream().anyMatch(q->q!=0))throw new IllegalStateException("funds/frozen/position conservation mismatch funds="+funds+" locked="+locked+" long="+positive+" short="+negative+" net="+netByInstrument);
  var mapper=new ObjectMapper();byte[] data=mapper.writeValueAsBytes(accounts);
  var result=new LinkedHashMap<String,Object>();result.put("status","PASS");result.put("productLine",product.name());result.put("accounts",1000);result.put("asset",asset);result.put("funds",funds);result.put("fundsDiff",0);result.put("locked",locked);result.put("reservations",0);result.put("positionCount",positionCount);result.put("longQuantity",positive);result.put("shortQuantity",negative);result.put("netPositionByInstrument",netByInstrument);result.put("accountStateSha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data)));result.put("accountStates",accounts);
  Files.writeString(Path.of(args[0]),mapper.writerWithDefaultPrettyPrinter().writeValueAsString(result));System.out.println("matchAudit=PASS fundsDiff=0 locked=0 reservations=0 long="+positive+" short="+negative+" accountStateSha256="+result.get("accountStateSha256"));
 }
}

